    fun materializePlan(id: Long): Plan = Plan(
        id = id,
        name = system.get(id, "name") as String,
        price = system.get(id, "price") as BigDecimal,
        members = (system.get(id, "members") as List<*>).map { MemberView(it as Long) },
    )

